+  private getCursorSort(orderBy: CrudOptions<T>['orderBy']) {
+    if (!orderBy) {
+      return [] as { field: string; direction: 'asc' | 'desc' }[];
+    }
+
+    const sort = (Array.isArray(orderBy) ? orderBy : [orderBy]).flatMap(
+      (part) =>
+        Object.entries(part).map(([field, value]) => ({
+          field,
+          direction: this.normalizeCursorDirection(value),
+        })),
+    );
+    const idField = this.crudConfig.id_field;
+    if (!sort.some(({ field }) => field === idField)) {
+      sort.push({ field: idField, direction: 'asc' });
+    }
+    return sort;
+  }
+
+  private normalizeCursorDirection(value: unknown): 'asc' | 'desc' {
+    if (value === 1) {
+      return 'asc';
+    }
+    if (value === -1) {
+      return 'desc';
+    }
+    const direction = String(value).toLowerCase();
+    if (direction.startsWith('asc')) {
+      return 'asc';
+    }
+    if (direction.startsWith('desc')) {
+      return 'desc';
+    }
+    throw new BadRequestException('orderBy direction must be asc or desc');
+  }
+
+  private parseCursor(
+    encodedCursor: string | undefined,
+    sort: { field: string; direction: 'asc' | 'desc' }[],
+  ): Record<string, any> | undefined {
+    if (encodedCursor === undefined) {
+      return undefined;
+    }
+    if (!sort.length) {
+      throw new BadRequestException('cursor requires orderBy');
+    }
+
+    let cursor: Record<string, any>;
+    try {
+      if (
+        !/^[A-Za-z0-9+/]*={0,2}$/.test(encodedCursor) ||
+        encodedCursor.length % 4 !== 0
+      ) {
+        throw new Error('invalid base64');
+      }
+      const decoded = new TextDecoder('utf-8', { fatal: true }).decode(
+        Buffer.from(encodedCursor, 'base64'),
+      );
+      cursor = JSON.parse(decoded);
+      if (!cursor || Array.isArray(cursor) || typeof cursor !== 'object') {
+        throw new Error('invalid cursor payload');
+      }
+    } catch {
+      throw new BadRequestException('cursor must be Base64-encoded JSON');
+    }
+
+    const serializedSort = sort
+      .map(({ field, direction }) => `${field}:${direction}`)
+      .join(',');
+    if (cursor.__sort !== serializedSort) {
+      throw new BadRequestException('cursor sort does not match orderBy');
+    }
+    for (const { field } of sort) {
+      if (!Object.prototype.hasOwnProperty.call(cursor, field)) {
+        throw new BadRequestException(`cursor is missing ${field}`);
+      }
+    }
+    return cursor;
+  }
+
+  private addCursorPredicate(
+    entity: Partial<T>,
+    sort: { field: string; direction: 'asc' | 'desc' }[],
+    cursor: Record<string, any>,
+  ): Partial<T> {
+    const predicates = sort.map(({ field, direction }, index) => {
+      const equalFields = Object.fromEntries(
+        sort.slice(0, index).map(({ field }) => [field, cursor[field]]),
+      );
+      return {
+        ...equalFields,
+        [field]: { [direction === 'asc' ? '$gt' : '$lt']: cursor[field] },
+      };
+    });
+    return {
+      $and: [entity, { $or: predicates }],
+    } as Partial<T>;
+  }
+
+  private createCursor(
+    entity: T,
+    sort: { field: string; direction: 'asc' | 'desc' }[],
+  ) {
+    const cursor = Object.fromEntries(
+      sort.map(({ field }) => [field, entity[field]]),
+    );
+    cursor.__sort = sort
+      .map(({ field, direction }) => `${field}:${direction}`)
+      .join(',');
+    return Buffer.from(JSON.stringify(cursor)).toString('base64');
+  }
